$b64 = $b64Parts -join ''
$bytes = [Convert]::FromBase64String($b64)

$tempZip = Join-Path $env:TEMP ('qiao_bowlong_' + [guid]::NewGuid().ToString('N') + '.zip')
[IO.File]::WriteAllBytes($tempZip, $bytes)

$target = Join-Path $env:LOCALAPPDATA 'Qiaoweilai\BowlongQuant'
Write-Host "安装目录: $target"

try {
    if (-not (Test-Path $target)) { New-Item -ItemType Directory -Path $target -Force | Out-Null }
    # ZIP 内顶层为 payload\...，解压到临时目录再复制到 target
    $tempDir = Join-Path $env:TEMP ('qiao_bowlong_ex_' + [guid]::NewGuid().ToString('N'))
    Expand-Archive -LiteralPath $tempZip -DestinationPath $tempDir -Force
    $src = Join-Path $tempDir 'payload'
    if (-not (Test-Path $src)) { throw '安装包结构异常：缺少 payload 目录' }
    Copy-Item -Path (Join-Path $src '*') -Destination $target -Recurse -Force
    foreach ($d in @('cache','logs')) {
        $p = Join-Path $target $d
        if (-not (Test-Path $p)) { New-Item -ItemType Directory -Path $p -Force | Out-Null }
    }
    Write-Host '[OK] 程序文件已安装'

    # 卸载脚本
    $uninstallPy = @'
# -*- coding: utf-8 -*-
import os, subprocess, base64, tempfile
APP = "巧未来-波龙量化"
KEY = r"Software\Microsoft\Windows\CurrentVersion\Uninstall\Qiaoweilai-BowlongQuant"
TARGET = os.path.dirname(os.path.abspath(__file__))
def ps(s):
    e = base64.b64encode(s.encode("utf-16le")).decode("ascii")
    subprocess.run(["powershell","-NoProfile","-NonInteractive","-ExecutionPolicy","Bypass","-EncodedCommand",e],capture_output=True)
def q(s): return "'" + s.replace("'","''") + "'"
lines = ["$ErrorActionPreference='SilentlyContinue'", "$ws=New-Object -ComObject WScript.Shell",
         "$d=[Environment]::GetFolderPath('Desktop')", "$s=[Environment]::GetFolderPath('StartMenu')",
         "Remove-Item -LiteralPath (Join-Path $d " + q(APP + '.lnk') + ") -Force",
         "Remove-Item -LiteralPath (Join-Path $s " + q('Programs\\' + APP) + ") -Recurse -Force"]
ps("\n".join(lines))
try:
    import winreg; winreg.DeleteKey(winreg.HKEY_CURRENT_USER, KEY)
except Exception: pass
bat = os.path.join(tempfile.gettempdir(), "_qiao_uninstall_%d.bat" % os.getpid())
with open(bat,"w",encoding="ascii") as f:
    f.write("@echo off\nping -n 3 127.0.0.1 >nul\nrmdir /s /q \"" + TARGET + "\"\ndel /f /q \"%~f0\"\n")
subprocess.Popen(["cmd","/c",bat], creationflags=getattr(subprocess,"CREATE_NO_WINDOW",0))
print("卸载完成，程序目录将在数秒后清理。")
'@
    $upy = Join-Path $target '_uninstall.py'
    [IO.File]::WriteAllText($upy, $uninstallPy, [Text.Encoding]::UTF8)
    $ubat = Join-Path $target 'uninstall.bat'
    $pyexe = Join-Path $target 'runtime\python\python.exe'
    @"
@echo off
cd /d "%~dp0"
set "PYEXE=%~dp0runtime\python\python.exe"
if not exist "%PYEXE%" set "PYEXE=python"
"%PYEXE%" "%~dp0_uninstall.py"
"@ | Out-File -FilePath $ubat -Encoding ascii

    # 快捷方式（UTF-8 编码脚本，WScript.Shell COM）
    $desk = [Environment]::GetFolderPath('Desktop')
    $sm = [Environment]::GetFolderPath('StartMenu')
    $folder = Join-Path $sm "Programs\$appName"
    if (-not (Test-Path $folder)) { New-Item -ItemType Directory -Path $folder -Force | Out-Null }
    $startBat = Join-Path $target 'start.bat'
    $ico = Join-Path $target 'runtime\python\python.exe'
    $ws = New-Object -ComObject WScript.Shell
    foreach ($lnkPath in @((Join-Path $desk "$appName.lnk"), (Join-Path $folder "$appName.lnk"))) {
        $lnk = $ws.CreateShortcut($lnkPath)
        $lnk.TargetPath = $startBat
        $lnk.WorkingDirectory = $target
        $lnk.Description = "$appName 量化交易终端"
        if (Test-Path $ico) { $lnk.IconLocation = "$ico,0" }
        $lnk.Save()
    }
    Write-Host '[OK] 桌面与开始菜单快捷方式已创建'

    # 注册表卸载项
    $key = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\Qiaoweilai-BowlongQuant"
    New-Item -Path $key -Force | Out-Null
    Set-ItemProperty -Path $key -Name DisplayName -Value $appName
    Set-ItemProperty -Path $key -Name DisplayVersion -Value $version
    Set-ItemProperty -Path $key -Name Publisher -Value '巧未来'
    Set-ItemProperty -Path $key -Name InstallLocation -Value $target
    Set-ItemProperty -Path $key -Name UninstallString -Value "`"$ubat`""
    Set-ItemProperty -Path $key -Name NoModify -Value 1
    Set-ItemProperty -Path $key -Name NoRepair -Value 1
    Write-Host '[OK] 已注册到"程序和功能"'

    # 清理临时文件
    Remove-Item -LiteralPath $tempZip -Force -ErrorAction SilentlyContinue
    Remove-Item -LiteralPath $tempDir -Recurse -Force -ErrorAction SilentlyContinue

    Write-Host '------------------------------------------------------------'
    Write-Host '安装完成！'
    Write-Host "  启动: 双击桌面【$appName】图标，或运行 $startBat"
    Write-Host '  访问: http://127.0.0.1:8765'
    Write-Host "  卸载: 控制面板-程序和功能，或运行 $ubat"
    Write-Host '------------------------------------------------------------'
} catch {
    Write-Host "[ERROR] 安装失败: $_"
    exit 1
}
